 17	// quoteToolArg puts s in quotes when it contains whitespace so the boundary
 18	// between a status message and the model-supplied argument it names is always
 19	// visible. Strings without whitespace are returned as-is. When s contains
 20	// double quotes but no single quotes, single-quoting is used instead of
 21	// escaping, because '"foo" bar' reads better than "\"foo\" bar".
 22	func quoteToolArg(s string) string {
 23		if !strings.ContainsAny(s, " \t\n\r") {
 24			return s
 25		}
 26	
 27		if strings.Contains(s, `"`) && !strings.Contains(s, `'`) {
 28			return `'` + s + `'`
 29		}
 30	
 31		return `"` + strings.ReplaceAll(s, `"`, `\"`) + `"`
 32	}
