 64	// runRead answers a read call with a numbered window of the file.
 65	func (i *Inspector) runRead(tc llm.ToolCall) string {
 66		var a struct {
 67			Path   string `json:"path"`
 68			Offset int    `json:"offset"`
 69			Limit  int    `json:"limit"`
 70		}
 71		if msg := decodeArgs(tc, &a); msg != "" {
 72			return msg
 73		}
 74		if strings.TrimSpace(a.Path) == "" {
 75			return "The required \"path\" argument was missing."
 76		}
 77	
 78		ft, err := i.Files.Read(a.Path, a.Offset, a.Limit)
 79		if err != nil {
 80			return fmt.Sprintf("Could not read %s: %v", quoteToolArg(a.Path), err)
 81		}
 82		i.Out.Toolf("Read %s", readSummary(ft))
 83	
 84		var b strings.Builder
 85		if ft.Link != "" {
 86			fmt.Fprintf(&b, "%s -> %s (%d lines)\n", ft.Path, ft.Link, ft.Total)
 87		} else {
 88			fmt.Fprintf(&b, "%s (%d lines)\n", ft.Path, ft.Total)
 89		}
 90		if len(ft.Lines) == 0 {
 91			fmt.Fprintf(&b, "\nLine %d is past the end of the file.\n", ft.Start)
 92			return b.String()
 93		}
 94		// Line numbers give stable referents for talking about code, which is worth
 95		// the tokens in a conversation that will discuss specific lines.
 96		width := len(strconv.Itoa(ft.Start + len(ft.Lines) - 1))
 97		for i, line := range ft.Lines {
 98			fmt.Fprintf(&b, "%*d\t%s\n", width, ft.Start+i, line)
 99		}
100		if ft.Truncated {
101			next := ft.Start + len(ft.Lines)
102			fmt.Fprintf(&b, "\n(Lines %d-%d of %d. Read from offset %d for more.)\n",
103				ft.Start, next-1, ft.Total, next)
104		}
105		return b.String()
106	}
