108	// readSummary is the one-line outcome shown to the user.
109	func readSummary(ft workspace.FileText) string {
110		p := quoteToolArg(ft.Path)
111		if len(ft.Lines) == 0 {
112			return fmt.Sprintf("%s (%d lines, nothing at offset %d)", p, ft.Total, ft.Start)
113		}
114		if ft.Start == 1 && !ft.Truncated {
115			return fmt.Sprintf("%s (%d lines)", p, ft.Total)
116		}
117		return fmt.Sprintf("%s (lines %d-%d of %d)", p, ft.Start, ft.Start+len(ft.Lines)-1, ft.Total)
118	}
