278	// runGlob answers a glob call.
279	func (i *Inspector) runGlob(tc llm.ToolCall) string {
280		var a struct {
281			Pattern string `json:"pattern"`
282		}
283		if msg := decodeArgs(tc, &a); msg != "" {
284			return msg
285		}
286		if strings.TrimSpace(a.Pattern) == "" {
287			return "The required \"pattern\" argument was missing."
288		}
289	
290		paths, trunc, err := i.Files.Glob(a.Pattern)
291		if err != nil {
292			return fmt.Sprintf("Could not match %s: %v", quoteToolArg(a.Pattern), err)
293		}
294		i.Out.Toolf("Matched %s against %s", plural(len(paths), "file", "files"), quoteToolArg(a.Pattern))
295	
296		if len(paths) == 0 {
297			// The same rules that make a grep glob silently admit nothing apply
298			// here, so the same explanation does. It is cheaper to say it than to
299			// let a caller conclude the files do not exist.
300			return fmt.Sprintf("No files match %s.\n\n%s", quoteToolArg(a.Pattern), globSyntaxNote)
301		}
302		var b strings.Builder
303		fmt.Fprintf(&b, "%s matching %s:\n\n", plural(len(paths), "file", "files"), quoteToolArg(a.Pattern))
304		b.WriteString(strings.Join(paths, "\n"))
305		b.WriteString("\n")
306		if trunc.Any() {
307			b.WriteString("\n(Results were cut short by a limit; narrow the pattern to see the rest.)\n")
308		}
309		return truncateResult(b.String())
310	}
