312	// runLS answers an ls call.
313	func (i *Inspector) runLS(tc llm.ToolCall) string {
314		var a struct {
315			Path string `json:"path"`
316		}
317		if msg := decodeArgs(tc, &a); msg != "" {
318			return msg
319		}
320	
321		entries, err := i.Files.List(a.Path)
322		if err != nil {
323			return fmt.Sprintf("Could not list %s: %v", displayDir(a.Path), err)
324		}
325		// The quotes quoteToolArg adds say "a literal argument with whitespace in
326		// it" — true of a path, false of the phrase that stands in for the empty
327		// one, which quoted reads as a directory named "the project root".
328		dir := displayDir(a.Path)
329		if strings.TrimSpace(a.Path) != "" {
330			dir = quoteToolArg(dir)
331		}
332		i.Out.Toolf("Listed %s (%s)", dir, plural(len(entries), "entry", "entries"))
333	
334		if len(entries) == 0 {
335			return displayDir(a.Path) + " is empty."
336		}
337		var b strings.Builder
338		fmt.Fprintf(&b, "%s:\n\n", displayDir(a.Path))
339		for _, e := range entries {
340			switch {
341			case e.IsDir:
342				fmt.Fprintf(&b, "%s/\n", e.Path)
343			case e.Link != "":
344				// Named the way ls -l names it. Without this a symlink and its
345				// target read as two identical files, and a model shown both spends
346				// the turn deciding which one is meant — observed live, on a
347				// dotfiles directory where aliases.sh links to real/aliases.sh.
348				fmt.Fprintf(&b, "%s -> %s\n", e.Path, e.Link)
349			default:
350				b.WriteString(e.Path + "\n")
351			}
352		}
353		return truncateResult(b.String())
354	}
